    'cdr_reports.help_body' => 'Liefert einen detaillierten Einzelverbindungsnachweis (CDR) aller eingehenden/ausgehenden Anrufe über die AI PBX und das Callcenter.',
    'cdr_reports.help_body2' => 'Jede Zeile ist ein Anruf: unter <b>Anrufer</b> der Trunk, über den er hereinkam, unter <b>Gewählt</b> die Route und, falls der Anruf die PBX verlassen hat, der Trunk und die gesendete Nummer; <b>Angenommen von</b> ist die Nebenstelle, die den Anruf entgegengenommen hat. <b>Richtung</b>: Eingehend, Ausgehend, Intern oder Trunk zu Trunk (kam über einen Trunk herein und ging über einen anderen hinaus, ohne dass eine AiPBX-Nebenstelle angenommen hat). Klappen Sie eine Zeile auf, um den Weg weitergeleiteter Anrufe zu sehen. Filtern Sie nach Datum, Status, Nebenstelle, Gerät, Richtung und Trunk; hören Sie Aufzeichnungen an oder laden Sie sie herunter.',
