    'asterisk_settings.rtp_section_title' => 'RTP-(Medien-)Einstellungen',
    'asterisk_settings.rtp_help_body' => 'Steuert, welcher Portbereich Audio (RTP) überträgt und ob Asterisk Audio aus einer unerwarteten Quelle ablehnt. Diese Datei (<code>/etc/asterisk/rtp.conf</code>) wird jetzt vom Panel erzeugt; manuelle Änderungen auf dem Server gehen beim nächsten „Übernehmen“ verloren.',
    'asterisk_settings.field_rtp_start' => 'RTP-Startport',
    'asterisk_settings.rtp_start_help' => 'Beginn des für Audiostreams reservierten Portbereichs. Jeder gleichzeitige Anruf belegt Ports aus diesem Bereich.',
    'asterisk_settings.field_rtp_end' => 'RTP-Endport',
    'asterisk_settings.rtp_end_help' => 'Ende des Bereichs. coturn (TURN-Relay) verwendet 13479-14999 — eine Überschneidung stört WebRTC-Audio und wird beim Speichern abgelehnt.',
    'asterisk_settings.field_rtp_strict' => 'Strict RTP (strictrtp)',
    'asterisk_settings.rtp_strict_help' => 'Wenn aktiviert, verwirft Asterisk stillschweigend Audio aus jeder anderen Quelle als der erlernten entfernten Adresse/Port (Angriffsschutz). Sendet die Gegenstellen-PBX Medien von einem unerwarteten Port, führt dies zu einem stillen „kein Ton“-Fehler ohne Logeintrag — zur Diagnose kann die Option vorübergehend deaktiviert werden.',
    'asterisk_settings.rtp_strict_yes' => 'Aktiviert (empfohlen)',
    'asterisk_settings.rtp_strict_no' => 'Deaktiviert (zur Diagnose)',
    'asterisk_settings.rtp_restart_warning' => 'Die Einstellung Strict RTP wird mit „Übernehmen“ wirksam. Eine Änderung des PORTBEREICHS erfordert dagegen einen vollständigen Asterisk-Neustart — der Portpool wird einmalig beim Laden des Moduls zugewiesen.',
    'asterisk_settings.udptl_section_title' => 'T.38-UDPTL-(Faxmedien-)Einstellungen',
    'asterisk_settings.udptl_help_body' => 'Definiert UDP-Portbereiche und Parameter der Vorwärtsfehlerkorrektur (FEC / Checksumme) für T.38-Faxpakete (UDPTL). Diese Datei (<code>/etc/asterisk/udptl.conf</code>) wird dynamisch verwaltet.',
    'asterisk_settings.field_udptl_start' => 'UDPTL-Startport',
    'asterisk_settings.udptl_start_help' => 'Start-UDP-Port für T.38-Faxstreams (Standard: 4100).',
    'asterisk_settings.field_udptl_end' => 'UDPTL-Endport',
    'asterisk_settings.udptl_end_help' => 'End-UDP-Port für T.38-Faxstreams (Standard: 4999).',
