    'trunks.field_connection_mode' => 'Verbindungsmodus',
    'trunks.connection_mode_ip' => 'IP-basiert (Gegenstelle hat eine statische IP)',
    'trunks.connection_mode_register' => 'Eingehende Registrierung (Gegenstelle registriert sich bei uns)',
    'trunks.connection_mode_help' => 'IP-basiert: Die Gegenstelle wird über ihre IP-Adresse identifiziert und ihr Kontakt bleibt statisch — der empfohlene Modus für eine Gegenstelle mit fester IP im selben Netz. Eingehende Registrierung: Die Gegenstelle sendet uns ein SIP REGISTER und ihre Adresse wird aus dieser Registrierung gelernt. Dieser Modus erfordert Benutzername und Passwort; die Gegenstelle authentifiziert damit sowohl ihre Registrierung als auch ihre Anrufe.',
    'trunks.connection_mode_warning' => 'Der Wechsel in den Registrierungsmodus entfernt den statischen Kontakt: Wir können diesen Trunk NICHT anrufen, BIS sich die Gegenstelle bei uns registriert. Nehmen Sie diese Änderung abgestimmt mit der Registrierungseinstellung auf der Gegenseite vor.',
