    'sound_packs.tab' => 'Asterisk-Sprachpakete',
    'sound_packs.title' => 'Offizielle Asterisk-Sprachpakete',
    'sound_packs.help_title' => 'Asterisk-Sprachpakete',
    'sound_packs.help_body' => 'Lädt die offiziellen Systemansagen und Wartemusik von Asterisk von <code>downloads.asterisk.org</code> herunter und installiert sie. Jedes Paket ist eine Sprache in einem Format; Asterisk spielt das zum Codec des Anrufs passende Format ab und transkodiert andernfalls (g722 für G.722, ulaw/alaw für Carrier).<br>- <strong>Core:</strong> Systemansagen, Ziffern, Voicemail. <strong>Extra:</strong> zusätzliche Ansagen; das Core-Paket derselben Sprache muss zuerst installiert sein.<br>- <strong>Wartemusik (opsound):</strong> wird nach <code>/var/lib/asterisk/moh/opsound</code> installiert; zum Abspielen auf dem Tab Wartemusik eine MOH-Klasse namens <strong>opsound</strong> anlegen.<br>- <strong>Türkçe (AiPBX):</strong> die eigenen türkischen Ansagen von AiPBX (GitHub-Release, SHA256-geprüft); die Standardsprache ist Türkisch, daher verstummen die Systemansagen, wenn sie entfernt werden. Beim Entfernen werden nur die vom Paket installierten Dateien gelöscht.',
