    'ms_teams.guide_title' => 'Anleitung zur Microsoft-Teams-Integration',
    'ms_teams.guide_intro' => 'AiPBX kann auf zwei verschiedenen Ebenen mit Microsoft Teams kommunizieren:',
    'ms_teams.guide_dr_title' => '1. Direct Routing (SBC / SIP-Trunk):',
    'ms_teams.guide_dr_desc' => 'Ermöglicht Teams-Benutzern, interne und externe Anrufe direkt über das Wählfeld von Teams Desktop/Mobil zu tätigen und zu empfangen. Erfordert TLS (Port 5061), SRTP und ein gültiges öffentliches SSL-Zertifikat (z. B. Let\'s Encrypt).',
    'ms_teams.guide_webhook_title' => '2. Webhooks & Kanalbenachrichtigungen:',
    'ms_teams.guide_webhook_desc' => 'Sendet interaktive Adaptive Cards an festgelegte Teams-Kanäle für verpasste Anrufe, Voicemails, eingehende Faxe und Callcenter-Warnungen. Erfordert keine Telefonielizenzen.',
    'ms_teams.guide_ps_title' => '3. Automatischer PowerShell-Generator:',
    'ms_teams.guide_ps_desc' => 'Erzeugen Sie im Tab „PowerShell-Anleitung“ mit einem Klick automatisch auf Ihre PBX-Einstellungen zugeschnittene PowerShell-Befehle zur Ausführung in Ihrer Microsoft-365-Administratorkonsole.',
