    'system_update.help_title' => 'Wie funktioniert das Update?',
    'system_update.help_body' => 'Das Update sichert zuerst die Datenbank, die Einstellungen und die Asterisk-Konfiguration, installiert dann die neue Version und testet, ob alles funktioniert. Schlägt etwas fehl, wird automatisch zur vorherigen Version zurückgekehrt. Asterisk wird während des Updates neu gestartet: Laufende Gespräche werden getrennt, daher startet es nicht, solange Anrufe aktiv sind. Es kann auch auf dem Server ausgeführt werden: <code>sudo aipbx-update</code>',
