    'certificates.help_title' => 'Hilfe zu Zertifikaten',
    'certificates.help_body' => 'Das Portal (HTTPS), WebRTC TURNS und SIP-TLS/WSS teilen sich ein Zertifikat; Änderungen hier werden gemeinsam auf Apache, coturn und Asterisk angewendet. <b>Let\'s Encrypt</b> ist kostenlos und erneuert sich selbst; die Domain muss auf diesen Server zeigen und Port 80 muss aus dem Internet erreichbar sein. Wenn Ihre Organisation ein Zertifikat hat, <b>laden Sie es hoch</b> (PEM oder PFX); hochgeladene Zertifikate erneuern sich nicht automatisch, laden Sie vor Ablauf ein neues hoch. Bei einem <b>selbstsignierten</b> Zertifikat zeigen Browser eine Warnung und TURNS funktioniert in Browsern nicht: WebRTC-Anrufe hinter Firewalls haben dann möglicherweise keinen Ton.',
