    'queue_reports.help_body' => 'Jeder Anruf, der eine Warteschlange betritt, wird einmal gezählt. <b>Angenommen</b>: mit einem Agenten verbunden. <b>Verloren</b>: Der Anrufer hat während des Wartens aufgelegt oder die Warteschlange hat das Zeitlimit erreicht. <b>Kurzabbruch</b>: innerhalb von %d Sekunden aufgelegt; wird beim Servicelevel nicht berücksichtigt. <b>Servicelevel</b>: innerhalb des Ziels angenommene Anrufe, bezogen auf alle Anrufe außer Kurzabbrüchen. <b>ASA</b>: durchschnittliche Wartezeit angenommener Anrufe. <b>AHT</b>: durchschnittliche Gesprächszeit. <b>Annahmequote</b> (Agent): wie oft der Agent angenommen hat, wenn die Warteschlange ihn angeklingelt hat. <b>Rückruf</b>: Ein verlorener Anruf gilt als erledigt, wenn seine Nummer später von einer Nebenstelle angerufen wurde oder erneut anrief und angenommen wurde. Die Daten stammen aus dem Warteschlangen-Log von Asterisk; der Bericht kann als PDF oder Excel heruntergeladen werden.',
