    'ai_tts.title' => 'Cloud-TTS (Text-to-Speech)',
    'ai_tts.help_title' => 'Hilfe zu Cloud-TTS',
    'ai_tts.help_body' => 'Wandelt Text mit Cloud-Diensten (Google, Amazon Polly, Azure, ElevenLabs, OpenAI) in natürliche Sprache um. Hören Sie das Ergebnis an, laden Sie es als MP3 herunter oder speichern Sie es mit einem Klick als <b>Ansage</b>: Es wird in das Asterisk-Format (8 kHz WAV) umgewandelt und unter Ansagen &amp; Sounds für IVRs, eingehende Routen und Zeitsteuerungen hinzugefügt (wirksam nach Übernehmen). <b>Diese Dienste sind kostenpflichtig</b> und rechnen pro Zeichen ab; jede Synthese wird mit ihrer Zeichenzahl im Verlauf gespeichert. Zugangsschlüssel stammen aus der Konsole des jeweiligen Anbieters, werden verschlüsselt gespeichert und nie wieder auf der Seite angezeigt.',
    'ai_tts.tab_speak' => 'Synthetisieren',
    'ai_tts.tab_providers' => 'Anbieter',
    'ai_tts.providers_text' => 'Geben Sie die Zugangsdaten der Dienste ein, die Sie nutzen möchten. Geheime Schlüssel werden verschlüsselt gespeichert; lassen Sie ein Schlüsselfeld leer, um den gespeicherten zu behalten.',
    'ai_tts.configured' => 'Verbunden',
