    'ai_tts.provider_hint_google' => 'Google Cloud Console → APIs &amp; Services: „Cloud Text-to-Speech API“ aktivieren; verwenden Sie einen JSON-Schlüssel eines Dienstkontos (IAM → Service Accounts → Keys → JSON) oder einen API-Schlüssel. Bis zu %s Zeichen pro Anfrage; längere Texte werden aufgeteilt.',
    'ai_tts.provider_hint_polly' => 'Erstellen Sie in AWS IAM einen Zugriffsschlüssel für einen Benutzer, der nur „polly:SynthesizeSpeech“ und „polly:DescribeVoices“ hat. Bis zu %s Zeichen pro Anfrage.',
    'ai_tts.provider_hint_azure' => 'Erstellen Sie im Azure-Portal eine „Speech“-Ressource; Schlüssel und Region (z. B. westeurope) finden Sie auf deren Seite „Keys and Endpoint“. Bis zu %s Zeichen pro Anfrage.',
    'ai_tts.provider_hint_elevenlabs' => 'ElevenLabs → Profile → API Keys. Die Stimmen stammen aus der Stimmbibliothek Ihres Kontos und sind mehrsprachig. Bis zu %s Zeichen pro Anfrage.',
