    'push.help_layer0' => '<strong>Schicht 0 (ohne Abhängigkeit - Standard):</strong> eine dauerhafte WSS-Verbindung, ein mit Android 15 kompatibler <code>specialUse</code>-Vordergrunddienst und ein Doze-resistenter <code>AlarmManager</code>-Watchdog, der ihn wiederbelebt. Kein externer Dienst nötig; Anrufe kommen auch an, wenn das Gerät im Ruhezustand oder der Bildschirm aus ist.',
    'push.help_layer1' => '<strong>Schicht 1 (optional - Google FCM):</strong> eine zusätzliche Aufweckgarantie auf OEM-Geräten mit aggressiven Akkubeschränkungen (Xiaomi, Huawei...) oder wenn der Benutzer die App weggewischt hat. <em>Sie greift nur, wenn die Nebenstelle keine aktive SIP-Registrierung hat, daher sehen registrierte Nebenstellen keine Verzögerung.</em>',
    'push.help_no_fcm' => 'Wenn Sie kein FCM möchten, lassen Sie den Anbieter auf <strong>„Lokal (ohne Abhängigkeit)“</strong>. Die mobile App nimmt dann überhaupt keinen Netzwerkkontakt zu Google auf.',
