    'mailtpl.invite_new.subject' => '[{brand}] Ihr Konto wurde angelegt - Passwort festlegen',
    'mailtpl.invite_new.body' => '<p>Hallo {name},</p><p>Ihr Konto auf der PBX <strong>{brand}</strong> ist bereit. Um sich anzumelden, legen Sie über die folgende Schaltfläche Ihr Passwort fest.</p>{account_details}{reset_button}<p>Falls die Schaltfläche nicht funktioniert, öffnen Sie diesen Link: {reset_link}</p>{mobile_section}<p><em>Der Passwortlink ist 48 Stunden gültig und funktioniert einmal. Wenn Sie diese E-Mail nicht erwartet haben, wenden Sie sich an Ihren Systemadministrator.</em></p>',
    'mailtpl.invite.subject' => '[{brand}] Ihr Anmelde- und Passwortlink',
    'mailtpl.invite.body' => '<p>Hallo {name},</p><p>hier ist ein neuer Link, um Ihr Passwort für <strong>{brand}</strong> festzulegen.</p>{account_details}{reset_button}<p>Falls die Schaltfläche nicht funktioniert, öffnen Sie diesen Link: {reset_link}</p>{mobile_section}<p><em>Der Passwortlink ist 48 Stunden gültig und funktioniert einmal. Wenn Sie ihn nicht angefordert haben, wenden Sie sich an Ihren Systemadministrator.</em></p>',
    'mailtpl.password_reset.subject' => '[{brand}] Passwort zurücksetzen',
    'mailtpl.password_reset.body' => '<p>Hallo {name},</p><p>für Ihr Konto <strong>{username}</strong> wurde das Zurücksetzen des Passworts angefordert.</p>{reset_button}<p>Falls die Schaltfläche nicht funktioniert, öffnen Sie diesen Link: {reset_link}</p><p><em>Der Link ist 30 Minuten gültig. Wenn Sie ihn nicht angefordert haben, ignorieren Sie diese E-Mail; Ihr Passwort bleibt unverändert.</em></p>',
    'mailtpl.voicemail.subject' => 'Neue Voicemail von {caller} ({duration})',
    'mailtpl.voicemail.body' => '<p>Hallo {name},</p><p>in Ihrem Postfach <strong>{mailbox}</strong> ist eine neue Voicemail-Nachricht eingegangen.</p><ul><li><strong>Von:</strong> {caller}</li><li><strong>Empfangen:</strong> {date}</li><li><strong>Länge:</strong> {duration}</li></ul><p>Ist die Aufzeichnung angehängt, können Sie sie direkt hier abspielen. Sie können sie auch im Portal ({portal_link}) oder durch Wählen von *97 anhören.</p>',
    'mailtpl.fax_received.subject' => 'Neues Fax empfangen - {department} ({did})',
    'mailtpl.fax_received.body' => '<p>Ein neues Fax ist eingegangen.</p><ul><li><strong>Einheit:</strong> {department}</li><li><strong>Faxnummer:</strong> {did}</li><li><strong>Von:</strong> {caller}</li><li><strong>Seiten:</strong> {pages}</li><li><strong>Empfangen:</strong> {date}</li></ul><p>Das Fax ist als PDF angehängt, wenn dies aktiviert ist. Alle Faxe finden Sie im Fax-Eingang: {portal_link}</p>',
