    'storage.help_title' => 'Wo Chatdateien gespeichert werden',
    'storage.help_body' => '<p>Chatanhänge, ihre Vorschaubilder und Gruppenbilder werden standardmäßig auf der Festplatte des Servers gespeichert (<code>/var/lib/aipbx/chat_files</code>). Mit einem S3-kompatiblen Speicher (AWS S3, MinIO, Wasabi, Backblaze B2, Cloudflare R2 …) landen sie stattdessen in einem Bucket, und große Dateien bleiben von der PBX fern.</p><p>Downloads laufen weiterhin über den Chatdienst, sodass nur die Teilnehmer eines Chats dessen Dateien öffnen können; der Bucket kann privat bleiben. Vor dem Wechsel gespeicherte Dateien werden weiter von der Festplatte ausgeliefert, bis Sie sie verschieben. Die Bucket-Einstellungen werden vor dem Speichern geprüft.</p><p>Gesprächsaufzeichnungen, Voicemail und Faxe bleiben auf der lokalen Festplatte.</p>',
