    'netsvc.help_title' => 'Netzwerkdienste',
    'netsvc.help_body' => 'Tischtelefone finden den Provisioning-Server selbst, wenn der DHCP-Server dessen Adresse verteilt (Option 66). DHCP und TFTP werden getrennt eingeschaltet. Ist der <strong>DHCP-Server</strong> aus, bleibt Ihr eigener DHCP-Server zuständig: Setzen Sie dort die unten aufgeführten Optionen. Ist er an, verteilt AiPBX Adressen auf einer Schnittstelle oder einem VLAN. Der <strong>TFTP-Server</strong> liefert die Boot-Dateien und Firmware aus, die Sie hochladen. Die Konfiguration je Telefon (mit dem SIP-Passwort) wird immer über HTTPS ausgeliefert, nie über TFTP.',
