    'web_widgets.help_title' => 'Anruf-Widget und Rückrufformular für Websites',
    'web_widgets.help_body' => 'Ein Widget setzt eine „Rufen Sie uns an“-Schaltfläche auf eine beliebige Website. Besucher sprechen über WebRTC direkt aus dem Browser mit Ihnen oder hinterlassen ihre Nummer, und die PBX ruft sie an. Fügen Sie den einzeiligen Code in die Website (oder in das WordPress-Plugin) ein und klicken Sie nach dem Speichern auf <strong>Übernehmen</strong>.',
    'web_widgets.help_number' => 'Nummer:',
    'web_widgets.help_number_desc' => 'Ein Widget kommt wie ein Trunk in die PBX. Seine Nummer ist die DID dieser Anrufe in Berichten und CDR; der Besucher wählt nie, wohin der Anruf geht.',
    'web_widgets.help_security' => 'Sicherheit:',
    'web_widgets.help_security_desc' => 'Nur die erlaubten Websites können das Widget verwenden. Jeder Anruf braucht ein Einmal-Token, und die Limits (pro IP, pro Tag, gleichzeitige Anrufe, Gesprächsdauer) gelten für jede Anfrage. Jede Anfrage wird unten protokolliert.',
    'web_widgets.help_callback' => 'Rückruf:',
    'web_widgets.help_callback_desc' => 'Die PBX ruft den Besucher über die gewählte ausgehende Route an und leitet ihn nach der Annahme zum Ziel weiter. Es werden nur Nummern mit den erlaubten Präfixen angerufen, und ein Tageslimit ist erforderlich.',
    'web_widgets.help_wordpress' => 'WordPress:',
    'web_widgets.help_wordpress_desc' => 'Installieren Sie das Plugin „AiPBX Call Widget“ (integrations/wordpress im Repository) und fügen Sie den Einbettungscode auf seiner Einstellungsseite ein.',
